// Single place for every outreach limit. Outside the sending window a live run stops here.
const DRY_RUN = true;
const TEST_ONLY_EMAIL = null;
const DAILY_CAP = 20;
const PER_RUN_CAP = 3;
const now = new Date();
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', weekday: 'short', hour12: false }).formatToParts(now).map(p => [p.type, p.value]));
const hour = Number(parts.hour);
const inWindow = !['Sat', 'Sun'].includes(parts.weekday) && hour >= 9 && hour < 18;
if (!DRY_RUN && !inWindow && !TEST_ONLY_EMAIL) return [];
const today = `${parts.year}-${parts.month}-${parts.day}`;
// Rome midnight as epoch seconds (offset probed so DST is handled)
const probe = new Date(`${today}T00:00:00Z`);
const romeAtProbe = new Date(probe.toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const utcAtProbe = new Date(probe.toLocaleString('en-US', { timeZone: 'UTC' }));
const dayStartEpoch = Math.floor((probe.getTime() - (romeAtProbe - utcAtProbe)) / 1000);
return [{ json: { dryRun: DRY_RUN, testOnlyEmail: TEST_ONLY_EMAIL, dailyCap: DAILY_CAP, perRunCap: PER_RUN_CAP, today, dayStartEpoch, inWindow } }];

function isChecked(v) {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') return ['TRUE', 'YES'].includes(v.trim().toUpperCase());
  return false;
}
const cfg = $('Config').first().json;
const GENERIC = new Set(['info', 'contact', 'contacts', 'hello', 'hi', 'hey', 'team', 'office', 'admin', 'support',
  'sales', 'press', 'media', 'marketing', 'hr', 'jobs', 'careers', 'enquiries', 'inquiries', 'enquiry', 'inquiry',
  'general', 'mail', 'email', 'founders', 'partnerships', 'partners', 'bd', 'business', 'ciao', 'hola', 'kontakt',
  'contatti', 'info.it', 'investors', 'ir', 'help', 'service', 'welcome']);
const JUNK_LOCAL = /^(no-?reply|do-?not-?reply|postmaster|abuse|privacy|legal|gdpr|dpo|unsubscribe|webmaster|billing|invoices?|accounts?|security|bounce|mailer-daemon)$/;
const JUNK_DOMAIN = /(^|\.)(example\.(com|org)|domain\.com|email\.com|sentry\.io|wixpress\.com|test\.com|yourdomain\.com)$/;
const EMAIL_RE = /^[a-z0-9._%+'-]+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/;

const rows = $('Pipeline - Get Rows').all().map(it => it.json);
const norm = e => String(e || '').trim().toLowerCase();
// Addresses already handled anywhere in the sheet (contacted, claimed, failed, under review)
const used = new Set(rows.filter(r => isChecked(r['Contacted']) || String(r['Outreach Status'] || '').trim())
  .map(r => norm(r['Email'])).filter(Boolean));

// First emails only: follow-ups ('Re: Plug and Play <> ...') have their own cap. Unknown subject counts (safe side).
const subjectOf = j => j.Subject || j.subject || ((j.payload && j.payload.headers) || []).find(h => /^subject$/i.test(h.name))?.value || '';
const sentInGmail = $('Gmail - Sent Today').all().filter(it => it.json && it.json.id && !/^\s*re:/i.test(subjectOf(it.json))).length;
const sentInSheet = rows.filter(r => String(r['Date Contacted'] || '').slice(0, 10) === cfg.today).length;
const sentToday = Math.max(sentInGmail, sentInSheet);
const remaining = Math.max(0, cfg.dailyCap - sentToday);
const limit = cfg.dryRun ? remaining : Math.min(cfg.perRunCap, remaining);

const FREE = /^(gmail|googlemail|outlook|hotmail|live|yahoo|icloud|me|aol|proton|protonmail|gmx|mail|yandex|zoho)\./;
const domainOf = e => (norm(e).split('@')[1] || '');
const siteOf = r => String(r['Website'] || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[\/?#]/)[0];
// Companies already handled: by email domain (not free mail) and by website domain.
const usedDomains = new Set(), usedSites = new Set();
for (const r of rows) {
  if (!(isChecked(r['Contacted']) || String(r['Outreach Status'] || '').trim())) continue;
  const d = domainOf(r['Email']); if (d && !FREE.test(d)) usedDomains.add(d);
  const w = siteOf(r); if (w) usedSites.add(w);
}
const out = [];
const seen = new Set();
for (const r of rows) {
  if (out.length >= limit) break;
  const email = norm(r['Email']);
  const name = String(r['Startup name'] || '').trim();
  if (!email || !name) continue;
  // 'Contact' (was 'Salesforce') is ticked by hand; 'Playbook' is the YES/NO dropdown written by Apollo Enrich.
  if (!isChecked(r['Contact']) || isChecked(r['Contacted']) || isChecked(r['Playbook'])) continue;
  // Only startups that Apollo Enrich actually checked on Playbook and did not find.
  if (!/^Not in Playbook/i.test(String(r['Playbook Check'] || '').trim())) continue;
  if (cfg.testOnlyEmail && email !== cfg.testOnlyEmail.toLowerCase()) continue;
  const d = domainOf(email), w = siteOf(r);
  if ((d && !FREE.test(d) && usedDomains.has(d)) || (w && usedSites.has(w))) continue;
  if (String(r['Meeting'] || '').trim() || String(r['Outreach Status'] || '').trim()) continue;
  if (Number(r['Outreach Count'] || 0) >= 3) continue;
  if (used.has(email) || seen.has(email)) continue;
  const [local, domain] = email.split('@');
  if (!EMAIL_RE.test(email) || JUNK_LOCAL.test(local) || JUNK_DOMAIN.test(domain)) continue;
  if (/\.(png|jpe?g|gif|svg|webp)$/.test(email)) continue;
  if (/test company|delete me/i.test(name) || name.length > 60) continue;
  seen.add(email);
  if (d && !FREE.test(d)) usedDomains.add(d);
  if (w) usedSites.add(w);
  out.push({ json: {
    row_number: r.row_number, name, email, website: String(r['Website'] || '').trim(),
    jobTitle: r['Job title'] || '', fullName: String(r['Full Name'] || '').trim(),
    generic: GENERIC.has(local.replace(/[0-9]+$/, '')), outreachCount: Number(r['Outreach Count'] || 0),
    sentToday, remainingToday: remaining,
  } });
}
return out;

const PARTNERS = {"SUSTAINABILITY": ["A2A", "Ayuntamiento de Jerez", "Alliance To End Plastic Waste", "Arizona Commerce Authority", "edotco Group"], "SMART CITIES": ["Abu Dhabi Ports", "AUPP", "CDP", "CenterPoint Energy", "Chiesi Farmaceutici", "City of Sugar Land"], "ENERGY": ["Acario Innovation LLC/Tokyo Gas Co., Ltd.", "Chiyoda Corporation", "Dentsu", "Duke Energy", "Electric Power Development", "ENEOS Corporation", "Eneva SA", "Eni"], "DEEPTECH": ["Acea", "Asahi Kasei Corporation", "Carbon Recycling Fund Inst.", "Dell Technologies", "DENKA", "Dexerials", "Doosan Bobcat"], "MOBILITY & PHYSICAL AI": ["ACN - Agenzia Cybersicurezza Nazionale", "Agrati", "AISIN", "Aspire", "Atlas SGR", "Audi", "BMW Group", "BNP Paribas", "BorgWarner", "Brightstar Lottery", "Dallara", "DXC Technology", "Ebersp\u00e4cher"], "TRAVEL & HOSPITALITY": ["Advanced Propulsion Centre", "Amex GBT", "Bentley Motors", "Cathay Pacific Airways", "Edmonton International Airport"], "INSURTECH": ["Aeroporti di Roma", "American Family Ventures", "AUPP Technology Center (ATC)", "Auto & General Insurance Company", "CMG Networks", "CNO Financial Group", "Daido Life", "EXL Services"], "FINTECH": ["Amazon", "American Family Ventures", "Ameriprise Financial", "Brave Connective", "Bremer Bank", "CoBank", "Creand", "Daiwa Capital Management", "EA Ventures", "Farm Credit East"], "ENTERPRISE & AI": ["Amex GBT", "ASUSTeK Computer, Inc.", "Bosch Germany", "Brisa Group", "BRIDG", "City of San Jose", "DivcoWest"], "SUPPLY CHAIN": ["ArcBest", "Arkansas Economic Development Commission", "CHEP / Brambles", "Crowley Maritime", "Cummins", "Daimler Truck North America", "Dell Technologies", "Dot Foods", "DSV - Global Transport and Logistics", "Equatorial Coca-Cola Bottling Company"], "AEROSPACE & DEFENSE": ["Armaereo", "Auto & General Insurance Company (adj.)", "Avio", "CMG Networks", "European Commission DG DEFIS"], "HEALTH": ["ART-ER Attractiveness Research Territory", "Astemo, Ltd.", "Bayer", "Brunel", "Eli Lilly and Company"], "ADVANCED MANUFACTURING": ["City of Cedar Park"], "REAL ESTATE & CONSTRUCTION": ["Daikin Industries"], "SEMICONDUCTORS": ["Bremer Bank (adj. ecosystem)"], "FOOD & BEVERAGE": ["CAAS Venture Network LLP", "Ezaki Glico", "PepsiCo"], "CRYPTO & DIGITAL ASSETS": ["XDC Network"], "BRAND & RETAIL": ["Aflac"], "GLOBAL OVERSEAS ACCELERATION & LEARNING (GOAL)": ["AADF - Albanian American Development Foundation", "AstraZeneca", "ASBIS", "Enterprise Singapore"]};
function stripTags(s) {
  return (s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
const originals = $('Select Candidates').all();
const out = [];
$input.all().forEach((item, i) => {
  const orig = originals[i].json;
  const html = typeof item.json.data === 'string' ? item.json.data : '';
  let siteSummary = '';
  if (html) {
    const titleMatch = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html);
    const descMatch = /<meta[^>]+name=["']description["'][^>]+content=["']([\s\S]*?)["']/i.exec(html);
    const parts = [];
    if (titleMatch) parts.push(stripTags(titleMatch[1]));
    if (descMatch) parts.push(stripTags(descMatch[1]));
    siteSummary = parts.join(' — ').slice(0, 400);
  }
  // Bot walls / empty pages are not a description of the startup.
  if (siteSummary.replace(/&#\d+;|&\w+;/g, '').trim().length < 20
      || /just a moment|attention required|access denied|enable javascript|checking your browser|403 forbidden|404 not found/i.test(siteSummary)) siteSummary = '';
  const prompt = "You are helping personalize a VC outreach email. Given a startup, pick the single best-fitting industry category from this list of Plug and Play corporate-partner verticals, and 1-2 of the most plausibly relevant partner names from that category's list:\n\n"
    + JSON.stringify(PARTNERS)
    + "\n\nStartup: " + orig.name + "\nWebsite: " + orig.website + "\n"
    + "What the startup's own homepage says about itself: " + (siteSummary || 'not available') + "\n"
    + "Founder/contact title: " + (orig.jobTitle || 'unknown') + "\n\n"
    + "Base the industry classification primarily on what the homepage says, not on the company name alone.\n"
    + 'Return ONLY JSON (no prose, no markdown fences): {"industry": "...", "partners": "..."}\n'
    + "industry: a natural, human-readable phrase for the vertical (e.g. \"mobility and physical AI\"), not the all-caps category label.\n"
    + 'partners: 1-2 partner names copied EXACTLY as written in the list, joined with " and ", e.g. "BMW Group and Bosch Germany" or "PepsiCo".';
  // No readable homepage: generic email, Claude is not asked to guess (tiny call keeps items aligned).
  if (!siteSummary) { out.push({ json: { prompt: 'Reply with exactly {}', max_tokens: 5, genericEmail: true } }); return; }
  out.push({ json: { prompt, max_tokens: 200 } });
});
return out;

const PARTNERS = {"SUSTAINABILITY": ["A2A", "Ayuntamiento de Jerez", "Alliance To End Plastic Waste", "Arizona Commerce Authority", "edotco Group"], "SMART CITIES": ["Abu Dhabi Ports", "AUPP", "CDP", "CenterPoint Energy", "Chiesi Farmaceutici", "City of Sugar Land"], "ENERGY": ["Acario Innovation LLC/Tokyo Gas Co., Ltd.", "Chiyoda Corporation", "Dentsu", "Duke Energy", "Electric Power Development", "ENEOS Corporation", "Eneva SA", "Eni"], "DEEPTECH": ["Acea", "Asahi Kasei Corporation", "Carbon Recycling Fund Inst.", "Dell Technologies", "DENKA", "Dexerials", "Doosan Bobcat"], "MOBILITY & PHYSICAL AI": ["ACN - Agenzia Cybersicurezza Nazionale", "Agrati", "AISIN", "Aspire", "Atlas SGR", "Audi", "BMW Group", "BNP Paribas", "BorgWarner", "Brightstar Lottery", "Dallara", "DXC Technology", "Ebersp\u00e4cher"], "TRAVEL & HOSPITALITY": ["Advanced Propulsion Centre", "Amex GBT", "Bentley Motors", "Cathay Pacific Airways", "Edmonton International Airport"], "INSURTECH": ["Aeroporti di Roma", "American Family Ventures", "AUPP Technology Center (ATC)", "Auto & General Insurance Company", "CMG Networks", "CNO Financial Group", "Daido Life", "EXL Services"], "FINTECH": ["Amazon", "American Family Ventures", "Ameriprise Financial", "Brave Connective", "Bremer Bank", "CoBank", "Creand", "Daiwa Capital Management", "EA Ventures", "Farm Credit East"], "ENTERPRISE & AI": ["Amex GBT", "ASUSTeK Computer, Inc.", "Bosch Germany", "Brisa Group", "BRIDG", "City of San Jose", "DivcoWest"], "SUPPLY CHAIN": ["ArcBest", "Arkansas Economic Development Commission", "CHEP / Brambles", "Crowley Maritime", "Cummins", "Daimler Truck North America", "Dell Technologies", "Dot Foods", "DSV - Global Transport and Logistics", "Equatorial Coca-Cola Bottling Company"], "AEROSPACE & DEFENSE": ["Armaereo", "Auto & General Insurance Company (adj.)", "Avio", "CMG Networks", "European Commission DG DEFIS"], "HEALTH": ["ART-ER Attractiveness Research Territory", "Astemo, Ltd.", "Bayer", "Brunel", "Eli Lilly and Company"], "ADVANCED MANUFACTURING": ["City of Cedar Park"], "REAL ESTATE & CONSTRUCTION": ["Daikin Industries"], "SEMICONDUCTORS": ["Bremer Bank (adj. ecosystem)"], "FOOD & BEVERAGE": ["CAAS Venture Network LLP", "Ezaki Glico", "PepsiCo"], "CRYPTO & DIGITAL ASSETS": ["XDC Network"], "BRAND & RETAIL": ["Aflac"], "GLOBAL OVERSEAS ACCELERATION & LEARNING (GOAL)": ["AADF - Albanian American Development Foundation", "AstraZeneca", "ASBIS", "Enterprise Singapore"]};
const PARTNER_SHORT = {"AADF - Albanian American Development Foundation": "AADF", "ACN - Agenzia Cybersicurezza Nazionale": "ACN", "ART-ER Attractiveness Research Territory": "ART-ER", "ASUSTeK Computer, Inc.": "ASUS", "AUPP Technology Center (ATC)": "AUPP", "Acario Innovation LLC/Tokyo Gas Co., Ltd.": "Tokyo Gas", "Ameriprise Financial": "Ameriprise", "Asahi Kasei Corporation": "Asahi Kasei", "Astemo, Ltd.": "Astemo", "Auto & General Insurance Company": "Auto & General", "Auto & General Insurance Company (adj.)": "Auto & General", "BMW Group": "BMW", "Bentley Motors": "Bentley", "Bosch Germany": "Bosch", "Bremer Bank (adj. ecosystem)": "Bremer Bank", "Brightstar Lottery": "Brightstar", "Brisa Group": "Brisa", "CAAS Venture Network LLP": "CAAS Venture Network", "CHEP / Brambles": "Brambles", "CNO Financial Group": "CNO Financial", "Carbon Recycling Fund Inst.": "Carbon Recycling Fund Institute", "Cathay Pacific Airways": "Cathay Pacific", "Chiesi Farmaceutici": "Chiesi", "Chiyoda Corporation": "Chiyoda", "Crowley Maritime": "Crowley", "DENKA": "Denka", "DSV - Global Transport and Logistics": "DSV", "DXC Technology": "DXC", "Daikin Industries": "Daikin", "Daimler Truck North America": "Daimler Truck", "Daiwa Capital Management": "Daiwa", "Dell Technologies": "Dell", "Doosan Bobcat": "Bobcat", "ENEOS Corporation": "ENEOS", "EXL Services": "EXL", "Electric Power Development": "J-POWER", "Eli Lilly and Company": "Eli Lilly", "Eneva SA": "Eneva", "Equatorial Coca-Cola Bottling Company": "Equatorial Coca-Cola Bottling", "European Commission DG DEFIS": "the European Commission", "Ezaki Glico": "Glico", "edotco Group": "edotco"};
const SIGNATURE_HTML = "\n<div style=\"color:rgb(68,68,68);font-family:sans-serif;line-height:1.5;font-size:12px\"><strong>Iacopo Bon</strong></div>\n<div style=\"color:rgb(68,68,68);font-family:sans-serif;line-height:1.5;font-size:12px\">\n  <div style=\"line-height:1.5\">Senior Associate</div>\n  <div style=\"line-height:1.5\"><strong><img src=\"https://3340630.fs1.hubspotusercontent-na1.net/hubfs/3340630/Email%20Signatures/PlugAndPlay%20Logo%20signature.png\" width=\"96\" height=\"34\"></strong></div>\n  <div style=\"line-height:1.5\"><a href=\"https://www.plugandplaytechcenter.com\" style=\"color:rgb(17,85,204)\" target=\"_blank\">plugandplaytechcenter.com</a></div>\n  <div style=\"line-height:1.5\"><a href=\"https://airtable.com/appdk7eWqstAib8LW/shrgeolZqg10b1qWW\" style=\"color:rgb(17,85,204)\" target=\"_blank\">Meet Our Portfolio</a></div>\n</div>\n<div style=\"color:rgb(68,68,68);font-family:sans-serif;font-size:12px\">\n  <div style=\"line-height:1.5\">Cell: 3409548428</div>\n</div>\n";
const CALENDLY_LINK = "https://calendly.com/i-bon";
const ALL_PARTNERS = [...new Set(Object.values(PARTNERS).flat())].sort((a, b) => b.length - a.length);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Generic inbox or no usable first name: "Dear <Startup>'s team" (legal suffix and tagline dropped).
function teamOf(name) {
  const full = String(name || '').trim();
  let n = full.split(/\s+[-|–—:]\s+/)[0];
  n = n.replace(/[,\s]+(inc|llc|ltd|limited|gmbh|ag|as|sa|sas|sl|s\.l|srl|bv|b\.v|ab|oy|corp|corporation|co)\.?$/i, '').trim().replace(/[,.]+$/, '');
  n = n || full;
  return n + (/s$/i.test(n) ? "'" : "'s") + ' team';
}
function greetingFor(c) {
  if (c.generic) return 'Dear ' + teamOf(c.name);
  const first = (c.fullName.split(/\s+/)[0] || '').replace(/[,.]+$/, '');
  if (!/^\p{L}[\p{L}'’-]{1,24}$/u.test(first)) return 'Dear ' + teamOf(c.name);
  const isOneCase = first === first.toUpperCase() || first === first.toLowerCase();
  return 'Hi ' + (isOneCase ? first[0].toUpperCase() + first.slice(1).toLowerCase() : first);
}
// Official names found in Claude's answer, in the order written; null if anything else is in it.
function partnersFound(p) {
  let rest = String(p || ''); const found = [];
  for (const name of ALL_PARTNERS) {
    const idx = rest.toLowerCase().indexOf(name.toLowerCase());
    if (idx >= 0) { found.push([idx, name]); rest = rest.slice(0, idx) + ' '.repeat(name.length) + rest.slice(idx + name.length); }
  }
  rest = rest.replace(/\band\b/gi, '').replace(/[,&\s]/g, '');
  if (found.length < 1 || found.length > 2 || rest !== '') return null;
  return found.sort((a, b) => a[0] - b[0]).map(f => f[1]);
}
const shortName = n => PARTNER_SHORT[n] || n;

const candidates = $('Select Candidates').all();
const prompts = $('Build Personalization Prompt').all();
const out = [];
$input.all().forEach((item, i) => {
  const c = candidates[i].json;
  const info = item.json || {};
  const base = { row_number: c.row_number, email: c.email, name: c.name, outreachCount: c.outreachCount };
  let reason = '';
  const genericEmail = !!(prompts[i] && prompts[i].json.genericEmail);
  const industry = String(info.industry || '').trim();
  const partners = String(info.partners || '').trim();
  if (genericEmail) reason = '';
  else if (info.error || !industry || !partners) reason = 'Claude returned no usable answer';
  else if (!/^[\p{L}][\p{L}\s&,\/'-]{2,60}$/u.test(industry)) reason = 'Odd industry text: ' + industry.slice(0, 60);
  else if (!partnersFound(partners)) reason = 'Partners not in the PnP list: ' + partners.slice(0, 80);
  if (reason) { out.push({ json: { ...base, valid: false, reason } }); return; }

  const greeting = greetingFor(c);
  const subject = 'Plug and Play <> ' + c.name;
  // Homepage unreadable: a generic email, no industry and no partner names (user's rule, 2026-11-04).
  const partnerText = genericEmail ? '' : partnersFound(partners).map(shortName).join(' and ') + ' among others';
  const intro = genericEmail
    ? "<p>I came across " + esc(c.name) + " while mapping out early-stage startups.</p><p>I'm on the Ventures team at Plug and Play Tech Center. We invest at the early stage (early backers of Dropbox, PayPal and Honey), but the bigger part of our model is commercial: we run innovation programs for corporate partners across many industries and introduce startups to the ones actively looking.</p>"
    : "<p>I came across " + esc(c.name) + " while mapping out startups in the " + esc(industry) + " space.</p><p>I'm on the Ventures team at Plug and Play Tech Center. We invest at the early stage (early backers of Dropbox, PayPal and Honey), but the bigger part of our model is commercial: we run innovation programs for corporate partners and introduce startups to the ones actively looking. In " + esc(industry) + " that includes " + esc(partnerText) + ".</p>";
  const html = "<p>" + esc(greeting) + ",</p>" + intro + "<p>Even if you aren't currently fundraising, I'd love to learn more about what you're building and see if there might be potential alignment with our ecosystem down the line.</p><p>Are you open to a quick 30 minute intro chat this week? Feel free to reply directly, or grab a slot on my calendar here: <a href=\"" + CALENDLY_LINK + "\">" + CALENDLY_LINK + "</a></p><p>Best,</p>" + SIGNATURE_HTML;
  if (/undefined|\bnull\b|NaN|\{\{|\}\}/.test(html + subject)) {
    out.push({ json: { ...base, valid: false, reason: 'Rendered email contains a placeholder' } }); return;
  }
  out.push({ json: { ...base, valid: true, subject, htmlBody: html, greeting, industry, partners } });
});
return out;

// DRY RUN: one preview email to the user, nothing sent to startups, nothing written to the sheet.
// On scheduled runs the same preview is not repeated.
const items = $input.all().map(it => it.json);
const first = $('Select Candidates').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const key = items.map(e => e.email + '|' + e.valid + '|' + (e.subject || e.reason)).join('\n');
const sd = $getWorkflowStaticData('global');
const manual = ['manual', 'test'].includes($execution.mode);
if (!manual && sd.lastDigestKey === key) return [];
sd.lastDigestKey = key;
const ok = items.filter(e => e.valid), bad = items.filter(e => !e.valid);
let html = `<p><b>DRY RUN - nessuna email inviata.</b> Gia' inviate oggi: ${first.sentToday} / 20. Nel live partirebbero max 3 ogni 15 min, lun-ven 9-18.</p>`;
html += `<p>Pronte: ${ok.length} - Da rivedere: ${bad.length}</p>`;
if (bad.length) html += '<ul>' + bad.map(e => `<li>${esc(e.name)} &lt;${esc(e.email)}&gt;: ${esc(e.reason)}</li>`).join('') + '</ul>';
for (const e of ok) html += `<hr><p><b>To:</b> ${esc(e.email)}<br><b>Subject:</b> ${esc(e.subject)}</p>${e.htmlBody}`;
return [{ json: { subject: `[DRY RUN] Outreach preview - ${ok.length} pronte, ${bad.length} da rivedere`, html } }];

// Hard block, independent of the sheet: if Gmail Sent holds ANY automated email
// ('Plug and Play <> ...' or 'Re: Plug and Play <> ...') to this address, ever, nothing is sent.
// A result whose subject can't be read also blocks (fail closed).
const e = $('Loop Over Emails').first().json;
const subjectOf = j => j.Subject || j.subject || ((j.payload && j.payload.headers) || []).find(h => /^subject$/i.test(h.name))?.value || '';
const hit = $input.all().some(it => it.json && it.json.id && (!subjectOf(it.json) || /plug and play <>/i.test(subjectOf(it.json))));
return [{ json: { ...e, alreadySent: hit } }];

const e = $('Already Sent Check').first().json;
return [{ json: { row_number: e.row_number, Contacted: true,
  'Outreach Status': 'Blocked: an automated email to this address is already in Gmail Sent ' + new Date().toISOString() } }];

const e = $('Already Sent Check').first().json;
const g = $input.first().json;
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Rome' }).format(new Date());
return [{ json: { row_number: e.row_number, Contacted: true, 'Date Contacted': today, 'Followed Up': false,
  'Outreach Count': (e.outreachCount || 0) + 1, 'Message ID': g.id || '', 'Thread ID': g.threadId || '',
  'Outreach Status': 'Sent ' + new Date().toISOString() } }];

// Not retried automatically: clear 'Outreach Status' in the sheet to try again.
const e = $('Already Sent Check').first().json;
const err = $input.first().json.error;
const msg = (err && (err.message || err.description)) || JSON.stringify(err || 'unknown');
return [{ json: { row_number: e.row_number, 'Outreach Status': 'Send failed: ' + String(msg).slice(0, 150) } }];
